<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { ShieldCheck, ArrowDown } from 'lucide-vue-next';
import { api } from '../api';
const rows = ref<any[]>([]), cursor = ref<string | null>(null), error = ref(''), busy = ref(false);
const timestamp = (v: string) => new Intl.DateTimeFormat('en-PH', { timeZone: 'Asia/Manila', dateStyle: 'medium', timeStyle: 'short' }).format(new Date(v));
async function load(more = false) { busy.value = true; error.value = ''; try { const result = await api(`/audit${more && cursor.value ? `?cursor=${cursor.value}` : ''}`); rows.value = more ? [...rows.value, ...result.rows] : result.rows; cursor.value = result.nextCursor; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } } onMounted(() => load());
</script>
<template><p v-if="error" class="alert error" role="alert">{{ error }}</p><section class="panel"><div class="panel-heading"><div><h2>System activity</h2><p>Enrollment, attendance corrections, account changes, and report access</p></div><ShieldCheck :size="22" class="muted" /></div><div v-if="!rows.length" class="empty-state"><ShieldCheck :size="32" /><h3>{{ busy ? 'Loading audit trail…' : 'No audit events yet' }}</h3><p>System actions are recorded automatically.</p></div><div v-else class="table-wrap"><table><thead><tr><th>When (PHT)</th><th>Action</th><th>Actor</th><th>Record</th><th>Details</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td class="nowrap">{{ timestamp(r.createdAt) }}</td><td><span class="audit-action">{{ r.action.toLowerCase().replaceAll('_', ' ') }}</span></td><td><code :title="r.actorId">{{ r.actorId.slice(0, 8) }}</code></td><td><code :title="r.entityId">{{ r.entityId.slice(0, 8) }}</code></td><td class="note-cell"><span v-for="(value, key) in r.metadata" :key="key" class="audit-detail"><strong>{{ key }}:</strong> {{ Array.isArray(value) ? value.join(', ') : value }}</span></td></tr></tbody></table></div><div v-if="cursor" class="load-more"><button class="button secondary" :disabled="busy" @click="load(true)"><ArrowDown :size="16" />{{ busy ? 'Loading…' : 'Load earlier activity' }}</button></div></section><p class="page-note">The application exposes no edit or delete action for audit events. Database triggers reject changes; independent backups are still required.</p></template>
